INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l7',4,2,7,'Bats','蝙蝠','部分否定(not all / not every)、so + 倒装(So was born…)/ so…that、by + 动名词(方式)+ 被动语态、定语从句中的介词 + 关系代词(on which / of which / in which)、not only…but + 现在分词作状语(NCE4 无 KS 页,考点由课文结构自取;原创承载·论蝙蝠的回声定位与船用回声测深仪、雷达原理相通的科普·题材无害;美语化 meter/analyze;第四册第7课·U2开工)','动物发出的声音并非都用作某种语言;有些声音有着纯粹实用、功利的用途。要充分领会这一点,不妨先看一项人类的发明。谁都知道,你在悬崖或高墙附近一喊,回声就会传回来。墙越远,回声传回前流逝的时间就越长。从船上向水下发出的声音会从海底反弹回来;通过测量声音发出到回声返回之间那极短的时间间隔,就能算出该处海水的深度。回声测深仪就这样诞生了,如今大多数船上都装了它。每一个实心物体都会反射声音,回声随物体的大小和性质而变。因此,从测定海底到探明鱼群,不过是一小步;凭借经验和更精良的设备,如今不仅能给鱼群定位,还能仅凭回声的模式,判断出那是鲱鱼、鳕鱼还是别的什么鱼。蝙蝠所做的事,竟惊人地相似。人们发现,许多蝙蝠飞行时会发出一连串高频的吱吱声;通过接收弹回的回声,它们能在黑暗中避开一切障碍,并找到赖以为食的飞虫。蝙蝠的这种回声定位常被拿来与雷达相比,二者原理十分相近:一个信号发出去,撞上障碍物再返回,生物便凭返回的回声,在看不见的世界里勾勒出一幅图景。','{"q":"Listen and answer — In what way does echo-location in bats play a utilitarian role?","options":["It helps them avoid obstacles and find food in the dark","It is used only for communication","It warns of bad weather","It has no real purpose"],"answer_index":0}'::jsonb,'{"title":"部分否定 / so 倒装 / by + 动名词 + 被动 / 介词 + 关系代词","intro":"①部分否定:not all / not every=“并非所有/每一…都…”。②so + 助/系动词 + 主语(倒装):So was born…;so…that=“如此…以至于”。③by + 动名词表方式,句子常用被动:by measuring…, the depth can be calculated。④定语从句里介词提前:the insects on which they feed;radar, the principle of which…。⑤not only…but(also)+ 现在分词作状语。","table":{"headers":["用法","结构","例子"],"rows":[["部分否定","not all / not every","Not all sounds are language"],["so 倒装","So + be/助动词 + 主语","So was born the apparatus"],["by + 动名词 + 被动","By doing…, … can be done","By measuring…, the depth can be calculated"],["介词 + 关系代词","on which / of which","insects on which they feed"]]},"specialRules":[{"rule":"not all / not every 是部分否定,“并非都”,不是“全不”;全否定要用 none / no。","mark":"Not all … (并非都)"},{"rule":"定语从句里介词提前时,指物用 which(不用 that);the principle of which=其原理。","mark":"on which / of which"},{"rule":"美式拼写:meter(米,英式 metre)、analyze(分析,英式 analyse)。本课已按美语写。","mark":"meter / analyze"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l7',1,NULL,'Not all the sounds made by animals serve as a kind of language; some have a strictly practical, utilitarian purpose. To gain a full appreciation of this, it helps to look first at a human invention. Everyone knows that if you shout near a cliff or a high wall, an echo comes back to you. The further off the wall, the longer the time that must elapse before the echo returns.','动物发出的声音并非都用作某种语言;有些声音有着纯粹实用、功利的用途。要充分领会这一点,不妨先看一项人类的发明。谁都知道,你在悬崖或高墙附近一喊,回声就会传回来。墙越远,回声传回前流逝的时间就越长。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l7',2,NULL,'A sound sent down through the water from a ship will bounce off the sea bottom, and by measuring the tiny interval between the sound and the returning echo, the depth of the sea at that point can be calculated. So was born the echo-sounding apparatus that is now fitted to most ships. Every solid object reflects sound, the echo varying according to the size and nature of the object.','从船上向水下发出的声音会从海底反弹回来;通过测量声音发出到回声返回之间那极短的时间间隔,就能算出该处海水的深度。回声测深仪就这样诞生了,如今大多数船上都装了它。每一个实心物体都会反射声音,回声随物体的大小和性质而变。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l7',3,NULL,'It is therefore only a short step from finding the sea bottom to finding a shoal of fish; with practice and better equipment, it is now possible not only to locate a shoal but also to tell whether it is herring, cod, or some other kind, simply by the pattern of its echo.','因此,从测定海底到探明鱼群,不过是一小步;凭借经验和更精良的设备,如今不仅能给鱼群定位,还能仅凭回声的模式,判断出那是鲱鱼、鳕鱼还是别的什么鱼。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l7',4,NULL,'Bats do something remarkably similar. It has been found that many bats emit a stream of high squeaks as they fly, and by catching the echoes that bounce back, they can steer clear of any obstruction in the dark and locate the flying insects on which they feed.','蝙蝠所做的事,竟惊人地相似。人们发现,许多蝙蝠飞行时会发出一连串高频的吱吱声;通过接收弹回的回声,它们能在黑暗中避开一切障碍,并找到赖以为食的飞虫。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l7',5,NULL,'This echolocation in bats is often compared with radar, the principle of which is much the same: a signal goes out, strikes an obstacle, and returns, and from the returning echo the creature builds a picture of the world it cannot see.','蝙蝠的这种回声定位常被拿来与雷达相比,二者原理十分相近:一个信号发出去,撞上障碍物再返回,生物便凭返回的回声,在看不见的世界里勾勒出一幅图景。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
