INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l9','act as','',NULL,'/ækt æz/','The king acted as his own spy.','国王亲自充当自己的间谍。','She acts as our guide.','她担任我们的向导。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l9','on the move','',NULL,'/ɑːn ðə muːv/','He kept his men always on the move.','他让部下始终在移动。','The army was constantly on the move.','军队不停地转移。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l9','no longer','',NULL,'/noʊ ˈlɔːŋɡər/','The raiders were no longer fit for battle.','袭掠者再也经不起打仗。','He is no longer young.','他不再年轻了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l9','cut off','',NULL,'/kʌt ɔːf/','They cut off the enemy''s supplies.','他们切断了敌人的补给。','The flood cut off the village.','洪水使村庄与外界隔绝。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp1','choice','{"stem":"\"The raiders ___ overrun his coast before he came.\"(过去完成时,填助动词)","options":["had","was","have","has"],"answer_index":0,"stem_cn":"在他来之前,袭掠者已侵占了他的海岸。","explanation_cn":"过去完成时 had + 过去分词,表比“他来”更早的过去;助动词用 had(不分单复数)。✓ The raiders had overrun his coast. ✗ have / has(过去完成用 had)/ was:助动词用 had。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp1','choice','{"stem":"\"By spring the invaders ___ already surrendered.\"(过去完成时,填助动词)","options":["did","have","were","had"],"answer_index":3,"stem_cn":"到春天,入侵者已经投降了。","explanation_cn":"过去完成时 had + 过去分词。✓ the invaders had already surrendered. ✗ have / did / were:过去完成助动词用 had。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp1','choice','{"stem":"\"Discipline had ___ slack over the winter.\"(过去完成 had + 过去分词;grow 的过去分词)","options":["grow","grew","grown","growing"],"answer_index":2,"stem_cn":"一冬下来纪律已变得松弛。","explanation_cn":"过去完成 had + 过去分词;grow 的过去分词是 grown。✓ discipline had grown slack. ✗ grew(过去式)/ grow(原形)/ growing:had 后用过去分词 grown。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp2','choice','{"stem":"\"___ as a wandering minstrel, the king entered the camp.\"(过去分词作状语,‘打扮成…’;dress 的过去分词)","options":["Dressed","Dressing","Dress","To dress"],"answer_index":0,"stem_cn":"装扮成流浪歌手,国王走进了营地。","explanation_cn":"过去分词短语作状语,表被动“被装扮成”;dress 的过去分词 Dressed。✓ Dressed as a minstrel, the king entered. ✗ Dressing(主动)/ Dress / To dress:被动伴随用过去分词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp2','choice','{"stem":"\"___ with the enemy''s advance, he chose not to fight.\"(过去分词作状语,‘面对…’;face 的过去分词)","options":["To face","Faced","Face","Facing"],"answer_index":1,"stem_cn":"面对敌人的推进,他选择不正面交战。","explanation_cn":"过去分词短语作状语,‘面对…’(be faced with);face 的过去分词 Faced。✓ Faced with the advance, he chose not to fight. ✗ Facing / Face / To face:此处用过去分词 Faced。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp2','choice','{"stem":"\"His force was tiny ___ with the enemy host.\"(过去分词短语,‘与…相比’)","options":["compared","comparing","compares","compare"],"answer_index":0,"stem_cn":"与敌军相比,他的部队小得可怜。","explanation_cn":"过去分词短语 compared with,‘与…相比’。✓ tiny compared with the enemy host. ✗ comparing / compare / compares:固定用过去分词 compared with。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp3','choice','{"stem":"\"___ well on stolen food, the raiders grew careless.\"(现在分词作状语,主动‘靠…生活’;live 的 -ing)","options":["To live","Lived","Live","Living"],"answer_index":3,"stem_cn":"靠抢来的粮食过着好日子,袭掠者变得松懈。","explanation_cn":"现在分词短语作状语,表主动“正靠…生活”;live 的 -ing 是 Living。✓ Living well on stolen food, the raiders grew careless. ✗ Lived / Live / To live:主动伴随用现在分词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp3','choice','{"stem":"\"He kept his men moving, ___ the enemy day and night.\"(现在分词作状语,主动‘骚扰’)","options":["harried","harry","harrying","to harry"],"answer_index":2,"stem_cn":"他让部下不停移动,日夜骚扰敌人。","explanation_cn":"现在分词短语作状语,表主动“骚扰”。✓ He kept his men moving, harrying the enemy. ✗ harried(被动/过去)/ harry / to harry:主动伴随用 -ing。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp3','choice','{"stem":"\"The king slipped in, ___ every weakness of the camp.\"(现在分词作状语,主动‘注意到’)","options":["to note","noting","noted","note"],"answer_index":1,"stem_cn":"国王潜入,留意着营地的每一处弱点。","explanation_cn":"现在分词短语作状语,表主动“注意到”。✓ He slipped in, noting every weakness. ✗ noted / note / to note:主动伴随用 -ing。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp4','choice','{"stem":"\"He stayed a week ___ he returned to the marshes.\"(‘在…之前’,填时间连词)","options":["unless","since","before","though"],"answer_index":2,"stem_cn":"他待了一周才回到沼泽地。","explanation_cn":"时间连词 before,‘在…之前’(引申“…才…”)。✓ He stayed a week before he returned. ✗ since / unless / though:表“之前”用 before。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp4','choice','{"stem":"\"___ his army was gathering, the king went spying.\"(‘当…的时候’,填时间连词)","options":["While","Before","Unless","Although"],"answer_index":0,"stem_cn":"当他的军队集结时,国王去做间谍。","explanation_cn":"时间连词 While,‘当…的时候’,引导正在进行的背景。✓ While his army was gathering, the king went spying. ✗ Before / Unless / Although:表“当…时”用 While。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp4','choice','{"stem":"\"He did not attack ___ his men were ready.\"(‘直到…才’,填时间连词)","options":["although","whether","until","since"],"answer_index":2,"stem_cn":"不到部下准备就绪,他不发动进攻。","explanation_cn":"时间连词 until,‘直到…(才)’。✓ He did not attack until his men were ready. ✗ since / although / whether:表“直到”用 until。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp5','choice','{"stem":"\"A season of comfort had made them ___.\"(make + 名词 + 形容词;填形容词)","options":["soft","soften","softly","softness"],"answer_index":0,"stem_cn":"一季的安逸把他们养软了。","explanation_cn":"make + 名词 + 形容词,形容词作补足语;此处填形容词 soft。✓ had made them soft. ✗ softly(副词)/ softness(名词)/ soften(动词):补足语用形容词 soft。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp5','choice','{"stem":"\"The king found the camp poorly ___.\"(find + 名词 + 过去分词‘被…’;guard 的过去分词)","options":["guarding","guarded","guard","guards"],"answer_index":1,"stem_cn":"国王发现营地守卫松懈。","explanation_cn":"find + 名词 + 过去分词,表“发现…被(守卫)”;guard 的过去分词 guarded。✓ found the camp poorly guarded. ✗ guarding / guard / guards:被动补足语用过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp5','choice','{"stem":"\"Constant raids kept the enemy ___ and tired.\"(keep + 名词 + 形容词;填形容词)","options":["hunger","hungrily","hungry","hungered"],"answer_index":2,"stem_cn":"不断的袭扰使敌人又饿又疲。","explanation_cn":"keep + 名词 + 形容词;填形容词 hungry。✓ kept the enemy hungry and tired. ✗ hunger(名词)/ hungrily(副词)/ hungered(动词):补足语用形容词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp6','choice','{"stem":"\"A person who wanders singing from place to place is a ___.\"(“流浪歌手/吟游诗人”用哪个词)","options":["minstrel","soldier","farmer","judge"],"answer_index":0,"stem_cn":"四处流浪卖唱的人。","explanation_cn":"四处流浪卖唱的人是 minstrel(吟游诗人)。✓ a wandering minstrel. ✗ soldier 士兵;✗ farmer 农夫;✗ judge 法官——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp6','choice','{"stem":"\"Secret watching to gather an enemy''s plans is ___.\"(“谍报/间谍活动”用哪个词)","options":["cooking","espionage","farming","trading"],"answer_index":1,"stem_cn":"暗中刺探敌方计划。","explanation_cn":"暗中刺探敌方计划是 espionage(谍报/间谍活动)。✓ royal espionage. ✗ farming 农业;✗ cooking 烹饪;✗ trading 贸易——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',5,'am4_l9_gp6','choice','{"stem":"\"A war or effort that lasts a long time is ___.\"(“持久的、长时间的”用哪个词)","options":["brief","tiny","sudden","prolonged"],"answer_index":3,"stem_cn":"持续很久的。","explanation_cn":"持续很久的是 prolonged(持久的)。✓ a prolonged campaign. ✗ brief 简短;✗ sudden 突然;✗ tiny 微小——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',6,NULL,'choice','{"stem":"espionage 的意思是:","options":["农业","烹饪","间谍活动,谍报","贸易"],"answer_index":2,"explanation_cn":"espionage = 间谍活动、谍报。✓ a small epic of royal espionage."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',6,NULL,'choice','{"stem":"minstrel 的意思是:","options":["吟游诗人,流浪歌手","农夫","士兵","法官"],"answer_index":0,"explanation_cn":"minstrel = 吟游诗人、流浪歌手。✓ dressed as a wandering minstrel."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',6,NULL,'choice','{"stem":"slack 的意思是:","options":["沉重的","紧张的","松弛的,懈怠的","勤奋的"],"answer_index":2,"explanation_cn":"slack = 松弛的、懈怠的。✓ discipline had grown slack."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',6,NULL,'choice','{"stem":"prolonged 的意思是:","options":["持久的,长时间的","突然的","简短的","微小的"],"answer_index":0,"explanation_cn":"prolonged = 持久的、长时间的。✓ a prolonged campaign."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',6,NULL,'choice','{"stem":"conjuring 的意思是:","options":["绘画","变戏法,魔术","舞蹈","唱歌"],"answer_index":1,"explanation_cn":"conjuring = 变戏法、魔术。✓ a little simple conjuring."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',6,NULL,'choice','{"stem":"episode 的意思是:","options":["(一段)经历,事件","计划","习惯","命令"],"answer_index":0,"explanation_cn":"episode = (一段)经历、事件。✓ the whole episode."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',7,NULL,'cloze','{"stem":"第 1 空","context":"King Aldric had ___1___ many ballads in his youth. Dressed ___2___ a minstrel, he entered the camp. He saw that discipline had grown ___3___. ___4___ his army gathered, he spied on the enemy.","blank_no":1,"options":["learned","learn","learning","learns"],"answer_index":0,"explanation_cn":"过去完成 had + 过去分词;learn 的过去分词 learned。✓ had learned many ballads."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',7,NULL,'cloze','{"stem":"第 2 空","context":"King Aldric had ___1___ many ballads in his youth. Dressed ___2___ a minstrel, he entered the camp. He saw that discipline had grown ___3___. ___4___ his army gathered, he spied on the enemy.","blank_no":2,"options":["as","like","for","with"],"answer_index":0,"explanation_cn":"过去分词短语 Dressed as,‘装扮成…’。✓ Dressed as a minstrel."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',7,NULL,'cloze','{"stem":"第 3 空","context":"King Aldric had ___1___ many ballads in his youth. Dressed ___2___ a minstrel, he entered the camp. He saw that discipline had grown ___3___. ___4___ his army gathered, he spied on the enemy.","blank_no":3,"options":["slack","slackly","slackness","slacken"],"answer_index":0,"explanation_cn":"grow + 形容词,‘变得松弛’;填形容词 slack。✓ discipline had grown slack."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',7,NULL,'cloze','{"stem":"第 4 空","context":"King Aldric had ___1___ many ballads in his youth. Dressed ___2___ a minstrel, he entered the camp. He saw that discipline had grown ___3___. ___4___ his army gathered, he spied on the enemy.","blank_no":4,"options":["While","Before","Unless","Although"],"answer_index":0,"explanation_cn":"时间连词 While,‘当…时’引导背景。✓ While his army gathered, he spied."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',8,NULL,'choice','{"stem":"What important thing did King Aldric learn inside the enemy camp?","options":["That the raiders had left","That the raiders wanted peace","That the raiders had more food than he did","That the raiders'' discipline was slack and they could not fight a long war"],"answer_index":3,"explanation_cn":"录音说国王探得的关键情报:袭掠者纪律松弛、经不起持久战。✓ slack discipline, cannot fight a long war."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',8,NULL,'choice','{"stem":"How did the king disguise himself?","options":["As a soldier","As a priest","As a wandering minstrel","As a merchant"],"answer_index":2,"explanation_cn":"录音说国王把自己装扮成一名流浪的吟游诗人潜入敌营。✓ as a wandering minstrel."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',8,NULL,'choice','{"stem":"How did Aldric finally defeat the raiders?","options":["By harrying them and cutting off supplies until they starved","By one great pitched battle","By paying them to leave","By burning their ships"],"answer_index":0,"explanation_cn":"录音说国王靠不停骚扰、切断补给,把敌人饿垮直至投降。✓ harry + cut off supplies."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',9,NULL,'choice','{"stem":"你想说\"在他到来之前,袭掠者已侵占了海岸\"(过去完成):","options":["Before he comes, the raiders had overrun the coast.","Before he came, the raiders had overrun the coast.","Before he came, the raiders have overrun the coast.","Before he came, the raiders had overran the coast."],"answer_index":1,"explanation_cn":"过去完成表“过去的过去”:先侵占(had overrun)在“他来”之前;overrun 的过去分词是 overrun(不是 overran)、主句用 had 不用 have、时间从句用一般过去 came。✓ had overrun. 场合:说“在…之前,早已…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',9,NULL,'choice','{"stem":"你想说\"装扮成流浪歌手,国王走进了营地\"(过去分词作状语):","options":["Dress as a wandering minstrel, the king entered the camp.","Dressing as a wandering minstrel, the king entered the camp.","Was dressed as a wandering minstrel, the king entered the camp.","Dressed as a wandering minstrel, the king entered the camp."],"answer_index":3,"explanation_cn":"过去分词短语作状语表被动“被装扮成”;用 Dressed 不用主动 Dressing、不用原形 Dress、也不加 Was(分词状语不带 be)。✓ Dressed as… 场合:说“(被)打扮成…做某事”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',9,NULL,'choice','{"stem":"你想说\"他待了一周才回到沼泽地\"(before 时间说法):","options":["He stayed a week before he returned to the marshes.","He stayed a week after he returned to the marshes.","He stayed a week before he returns to the marshes.","He stayed a week until before he returned to the marshes."],"answer_index":0,"explanation_cn":"before 引导时间从句表“…之后才…”;从句用一般过去 returned、不用现在 returns、不叠加 until、语义上不是 after。✓ before he returned. 场合:说“过了…才…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',10,NULL,'choice','{"stem":"espionage 的意思是:","options":["贸易","农业","烹饪","间谍活动,谍报"],"answer_index":3,"explanation_cn":"espionage = 间谍活动、谍报。✓ royal espionage."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',10,NULL,'choice','{"stem":"prolonged 的意思是:","options":["微小的","简短的","持久的,长时间的","突然的"],"answer_index":2,"explanation_cn":"prolonged = 持久的、长时间的。✓ a prolonged campaign."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',10,NULL,'choice','{"stem":"\"The raiders ___ overrun his coast before he came.\"(过去完成时)","options":["has","had","was","have"],"answer_index":1,"stem_cn":"在他来之前,袭掠者已侵占了海岸。","explanation_cn":"过去完成时 had + 过去分词。✓ The raiders had overrun his coast. ✗ have / has / was。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',10,NULL,'choice','{"stem":"\"___ as a minstrel, the king entered the camp.\"(过去分词作状语)","options":["Dressed","Dressing","Dress","To dress"],"answer_index":0,"stem_cn":"装扮成歌手,国王走进营地。","explanation_cn":"过去分词短语作状语,‘(被)装扮成’。✓ Dressed as a minstrel, the king entered. ✗ Dressing / Dress / To dress。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',10,NULL,'choice','{"stem":"\"act as\" 的意思是:","options":["出发","忘记","拒绝","充当、担任"],"answer_index":3,"explanation_cn":"act as = 充当、担任。✓ acted as his own spy."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',10,NULL,'choice','{"stem":"\"on the move\" 的意思是:","options":["在睡觉","在开会","在行进中、不停移动","静止不动"],"answer_index":2,"explanation_cn":"on the move = 在行进中、不停移动。✓ always on the move."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',10,NULL,'choice','{"stem":"Why was Aldric able to enter the enemy camps freely?","options":["He was invited by the enemy king","Wandering minstrels were welcomed everywhere","He came with an army","He bribed the guards"],"answer_index":1,"passage":"King Aldric chose to act as his own spy. Dressed as a wandering minstrel, he walked freely into the camps of the raiders who had overrun his coast, for in those days a traveling minstrel was welcomed everywhere; such men were not soldiers, and their songs were their passport. Aldric had learned dozens of old ballads in his boyhood, and he could brighten any evening with a few acrobatic tricks and a little simple conjuring. While his own small army was still gathering in the marshes, the king slipped into the heart of the enemy''s winter camp. He noticed at once that discipline had grown slack. The raiders had the easy confidence of conquerors who had never been beaten, and their guards kept watch carelessly. They had settled in for the cold months, living well on all that they had seized from the villages around, and a season of comfort had made them soft. Aldric stayed among them for a week before he returned to his marshes. The force he had gathered there was tiny compared with the enemy host, yet he had deduced something priceless: the raiders were no longer fit for a prolonged campaign, and their supplies had no real order but depended on scattered plunder. So, faced with the enemy''s slow advance, Aldric did not risk one great battle. Instead he kept his men always on the move, harrying the enemy and cutting off their foraging parties until hunger did his work for him. Within a single month the invaders, worn down and starving, had surrendered — and the whole episode could fairly be called a small epic of royal espionage.","explanation_cn":"课文说那年头四处卖唱的吟游诗人到哪儿都受欢迎,所以国王能自由出入敌营。✓ minstrels welcomed everywhere."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',10,NULL,'choice','{"stem":"What did Aldric conclude about the raiders?","options":["They were no longer fit for a prolonged campaign","They were the strongest army in the world","They had plenty of supplies","They wished to make a lasting pact"],"answer_index":0,"passage":"King Aldric chose to act as his own spy. Dressed as a wandering minstrel, he walked freely into the camps of the raiders who had overrun his coast, for in those days a traveling minstrel was welcomed everywhere; such men were not soldiers, and their songs were their passport. Aldric had learned dozens of old ballads in his boyhood, and he could brighten any evening with a few acrobatic tricks and a little simple conjuring. While his own small army was still gathering in the marshes, the king slipped into the heart of the enemy''s winter camp. He noticed at once that discipline had grown slack. The raiders had the easy confidence of conquerors who had never been beaten, and their guards kept watch carelessly. They had settled in for the cold months, living well on all that they had seized from the villages around, and a season of comfort had made them soft. Aldric stayed among them for a week before he returned to his marshes. The force he had gathered there was tiny compared with the enemy host, yet he had deduced something priceless: the raiders were no longer fit for a prolonged campaign, and their supplies had no real order but depended on scattered plunder. So, faced with the enemy''s slow advance, Aldric did not risk one great battle. Instead he kept his men always on the move, harrying the enemy and cutting off their foraging parties until hunger did his work for him. Within a single month the invaders, worn down and starving, had surrendered — and the whole episode could fairly be called a small epic of royal espionage.","explanation_cn":"课文说国王探明:袭掠者已经不再经得起一场持久的战役。✓ no longer fit for a prolonged campaign."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',10,NULL,'choice','{"stem":"What did the king notice about the raiders'' discipline?","options":["It was unknown","It improved daily","It was very strict","It had grown slack"],"answer_index":3,"audio":"King Aldric chose to act as his own spy. Dressed as a wandering minstrel, he walked freely into the camps of the raiders who had overrun his coast, for in those days a traveling minstrel was welcomed everywhere; such men were not soldiers, and their songs were their passport. Aldric had learned dozens of old ballads in his boyhood, and he could brighten any evening with a few acrobatic tricks and a little simple conjuring. While his own small army was still gathering in the marshes, the king slipped into the heart of the enemy''s winter camp. He noticed at once that discipline had grown slack. The raiders had the easy confidence of conquerors who had never been beaten, and their guards kept watch carelessly. They had settled in for the cold months, living well on all that they had seized from the villages around, and a season of comfort had made them soft. Aldric stayed among them for a week before he returned to his marshes. The force he had gathered there was tiny compared with the enemy host, yet he had deduced something priceless: the raiders were no longer fit for a prolonged campaign, and their supplies had no real order but depended on scattered plunder. So, faced with the enemy''s slow advance, Aldric did not risk one great battle. Instead he kept his men always on the move, harrying the enemy and cutting off their foraging parties until hunger did his work for him. Within a single month the invaders, worn down and starving, had surrendered — and the whole episode could fairly be called a small epic of royal espionage.","explanation_cn":"课文说国王一眼看出敌人的纪律已经松弛。✓ discipline had grown slack."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l9',10,NULL,'choice','{"stem":"How did hunger help Aldric?","options":["It had no effect","It made his own men flee","It wore the raiders down until they surrendered","It forced a great battle"],"answer_index":2,"audio":"King Aldric chose to act as his own spy. Dressed as a wandering minstrel, he walked freely into the camps of the raiders who had overrun his coast, for in those days a traveling minstrel was welcomed everywhere; such men were not soldiers, and their songs were their passport. Aldric had learned dozens of old ballads in his boyhood, and he could brighten any evening with a few acrobatic tricks and a little simple conjuring. While his own small army was still gathering in the marshes, the king slipped into the heart of the enemy''s winter camp. He noticed at once that discipline had grown slack. The raiders had the easy confidence of conquerors who had never been beaten, and their guards kept watch carelessly. They had settled in for the cold months, living well on all that they had seized from the villages around, and a season of comfort had made them soft. Aldric stayed among them for a week before he returned to his marshes. The force he had gathered there was tiny compared with the enemy host, yet he had deduced something priceless: the raiders were no longer fit for a prolonged campaign, and their supplies had no real order but depended on scattered plunder. So, faced with the enemy''s slow advance, Aldric did not risk one great battle. Instead he kept his men always on the move, harrying the enemy and cutting off their foraging parties until hunger did his work for him. Within a single month the invaders, worn down and starving, had surrendered — and the whole episode could fairly be called a small epic of royal espionage.","explanation_cn":"课文说饥饿把袭掠者拖垮,不出一个月他们便投降了。✓ hunger wore them down until they surrendered."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
